/**
 * better-auth Server Configuration
 *
 * Email + password authentication with the username and organization
 * (multi-tenant, teams enabled) plugins. Sessions are persisted in
 * PostgreSQL via the drizzle adapter and cached in Redis (secondary
 * storage). Record identifiers are generated by the database (UUID v7),
 * hence `advanced.database.generateId: false`.
 */

import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { organization, username } from "better-auth/plugins";
import { tanstackStartCookies } from "better-auth/tanstack-start";
import { createClient } from "redis";

import { APPLICATION_BASE_URL } from "../configuration/application";
import { KEY_PREFIX } from "../configuration/global";
import { REDIS_URI } from "../configuration/redis";
import { seedDefaultStages } from "../server/organization-defaults.server";
import { drizzleClient } from "../_drizzle/client";
import {
  betterauthAccountTable,
  betterauthInvitationTable,
  betterauthMemberTable,
  betterauthOrganizationTable,
  betterauthSessionTable,
  betterauthTeamMemberTable,
  betterauthTeamTable,
  betterauthUserTable,
  betterauthVerificationTable,
} from "../_drizzle/schema/better-auth";

// Must match the `betterauth_` prefix used in `schema/better-auth.ts`.
const P = "betterauth_";

const redis = createClient({ url: REDIS_URI });
await redis.connect();

export const auth = betterAuth({
  appName: "Dori",
  baseURL: APPLICATION_BASE_URL,
  secret: process.env.BETTER_AUTH_SECRET,
  // Database
  database: drizzleAdapter(drizzleClient, {
    provider: "pg",
    schema: {
      [`${P}user`]: betterauthUserTable,
      [`${P}session`]: betterauthSessionTable,
      [`${P}account`]: betterauthAccountTable,
      [`${P}verification`]: betterauthVerificationTable,
      [`${P}organization`]: betterauthOrganizationTable,
      [`${P}member`]: betterauthMemberTable,
      [`${P}invitation`]: betterauthInvitationTable,
      [`${P}team`]: betterauthTeamTable,
      [`${P}team_member`]: betterauthTeamMemberTable,
    },
  }),
  // Core model → table-name mapping
  user: { modelName: `${P}user` },
  session: {
    modelName: `${P}session`,
    expiresIn: 60 * 60 * 24 * 7, // 7 days
    updateAge: 60 * 60 * 24, // refresh once per day
    cookieCache: {
      enabled: true,
      maxAge: 60 * 5, // 5 minutes
    },
  },
  account: { modelName: `${P}account` },
  verification: { modelName: `${P}verification` },
  // Secondary storage (Redis) for sessions and rate limiting
  secondaryStorage: {
    get: async (key) => {
      return await redis.get(`${KEY_PREFIX}${key}`);
    },
    set: async (key, value, ttl) => {
      if (ttl) await redis.set(`${KEY_PREFIX}${key}`, value, { EX: ttl });
      else await redis.set(`${KEY_PREFIX}${key}`, value);
    },
    delete: async (key) => {
      await redis.del(`${KEY_PREFIX}${key}`);
    },
    getAndDelete: async (key) => {
      // Atomic get-and-delete (Redis 6.2+ GETDEL).
      return await redis.getDel(`${KEY_PREFIX}${key}`);
    },
    increment: async (key, ttl) => {
      // Atomically increment; apply the TTL only when the key is created.
      const namespaced = `${KEY_PREFIX}${key}`;
      const value = await redis.incr(namespaced);
      if (value === 1 && ttl) await redis.expire(namespaced, ttl);
      return value;
    },
  },
  // Authentication methods
  emailAndPassword: {
    enabled: true,
    minPasswordLength: 8,
  },
  // Plugins
  plugins: [
    username(),
    organization({
      teams: { enabled: true },
      organizationHooks: {
        // Seed a default sales pipeline for every new organization.
        afterCreateOrganization: async ({ organization, user }) => {
          await seedDefaultStages(organization.id, user.id);
        },
      },
      schema: {
        organization: { modelName: `${P}organization` },
        member: { modelName: `${P}member` },
        invitation: { modelName: `${P}invitation` },
        team: { modelName: `${P}team` },
        teamMember: { modelName: `${P}team_member` },
      },
    }),
    // Must be the last plugin in the array.
    tanstackStartCookies(),
  ],
  // Advanced — database generates UUID v7 identifiers.
  advanced: {
    database: {
      generateId: false,
    },
  },
});
